-- Base de datos de Turismo Neuquino.
-- Requiere max_allowed_packet de al menos 16M en el servidor, porque las fotos viajan dentro de las consultas.

CREATE DATABASE IF NOT EXISTS turismoneuquino CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE turismoneuquino;

SET NAMES utf8mb4;

CREATE TABLE destinos (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    nombre VARCHAR(120) NOT NULL,
    localidad_cercana VARCHAR(120) NULL,
    departamento VARCHAR(80) NOT NULL,
    descripcion TEXT NOT NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL,
    PRIMARY KEY (id),
    UNIQUE KEY destinos_nombre_unique (nombre)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE imagenes (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    destino_id BIGINT UNSIGNED NOT NULL,
    titulo VARCHAR(120) NOT NULL,
    hash_hex CHAR(16) NOT NULL,
    mime_type VARCHAR(50) NOT NULL,
    contenido MEDIUMBLOB NOT NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL,
    PRIMARY KEY (id),
    KEY imagenes_destino_id_foreign (destino_id),
    CONSTRAINT imagenes_destino_id_foreign FOREIGN KEY (destino_id) REFERENCES destinos (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

